"""ex02 工具参数 schema 校验：类型 / 枚举 / 范围 / 必填 / 未知参数。"""

SCHEMA = {
    "name": "get_weather",
    "parameters": {
        "city": {"type": "string", "required": True, "min_len": 2},
        "unit": {"type": "string", "enum": ["c", "f"], "required": False, "default": "c"},
        "days": {"type": "integer", "required": False, "min": 1, "max": 7, "default": 1},
    },
}


def validate(args, schema):
    """返回可行动的错误列表；空列表表示校验通过。"""
    errors = []
    params = schema["parameters"]
    for name, spec in params.items():
        if name not in args:
            if spec.get("required"):
                errors.append("%s: 缺少必填参数 %s" % (schema["name"], name))
            continue
        v = args[name]
        t = spec["type"]
        # 注意 bool 是 int 的子类，必须先排除
        if t == "string" and not isinstance(v, str):
            errors.append("参数 %s 应为 string，实际 %s" % (name, type(v).__name__))
            continue
        if t == "integer" and (isinstance(v, bool) or not isinstance(v, int)):
            errors.append("参数 %s 应为 integer，实际 %s" % (name, type(v).__name__))
            continue
        if t == "string" and "min_len" in spec and len(v) < spec["min_len"]:
            errors.append("参数 %s 长度须 >= %d，实际 %d" % (name, spec["min_len"], len(v)))
        if "enum" in spec and v not in spec["enum"]:
            errors.append("参数 %s 只允许 %s，实际 %r" % (name, spec["enum"], v))
        if "min" in spec and v < spec["min"]:
            errors.append("参数 %s 须 >= %d，实际 %d" % (name, spec["min"], v))
        if "max" in spec and v > spec["max"]:
            errors.append("参数 %s 须 <= %d，实际 %d" % (name, spec["max"], v))
    for name in args:
        if name not in params:
            errors.append("未知参数 %s（不在 schema 中，可能是模型幻觉）" % name)
    return errors


CASES = [
    ("正例：完整合法", {"city": "Beijing", "unit": "c", "days": 3}),
    ("反例：city 传成了数字", {"city": 42}),
    ("反例：unit 不在枚举内", {"city": "Paris", "unit": "kelvin"}),
    ("反例：days 超出上限", {"city": "Tokyo", "days": 30}),
    ("反例：缺必填 + 多幻觉参数", {"temp": 25}),
]

if __name__ == "__main__":
    ok_n = bad_n = 0
    for title, args in CASES:
        errs = validate(args, SCHEMA)
        if errs:
            bad_n += 1
            print("%s -> 拒绝(%d 条原因)" % (title, len(errs)))
            for e in errs:
                print("    - %s" % e)
        else:
            ok_n += 1
            print("%s -> 通过" % title)
    print("通过 %d 例，拒绝 %d 例" % (ok_n, bad_n))
